# bash-completion targets bash 4.2 or later, and so does this file
# (`declare -gA` below). Older shells, such as the bash 3.2 macOS ships
# as /bin/bash, get no vmaf completion instead of errors at startup.
if ((BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 2))); then
  return 0
fi

# Every COMPREPLY goes through this helper: feeding compgen into the
# array with a command substitution would trip shellcheck's SC2207.
_vmaf_compgen() {
  local word
  COMPREPLY=()
  while IFS="" read -r word; do
    COMPREPLY+=("${word}")
  done < <(compgen "$@")
}

# One entry per spelling of every value-domain option; the option's
# argument completes from its own words. `declare -g` because
# bash-completion sources this file inside a function, where a plain
# `declare -A` would be local and gone before `_vmaf` runs.
declare -gA _vmaf_values=(
  ["--pixel_format"]="400 420 422 444 nv12 nv16 nv24 p010 p016 p210 p216 p410 p416 yuyv422 uyvy422 v210 y210 y212 xv30 xv36 vuyx ayuv yuv444p16msb rgb rgba bgra"
  ["-p"]="400 420 422 444 nv12 nv16 nv24 p010 p016 p210 p216 p410 p416 yuyv422 uyvy422 v210 y210 y212 xv30 xv36 vuyx ayuv yuv444p16msb rgb rgba bgra"
  ["--color_range_ref"]="unknown limited full"
  ["--color_range_dist"]="unknown limited full"
  ["--color_primaries_ref"]="unknown bt709 bt2020"
  ["--color_primaries_dist"]="unknown bt709 bt2020"
  ["--color_trc_ref"]="unknown bt709 smpte2084 pq"
  ["--color_trc_dist"]="unknown bt709 smpte2084 pq"
  ["--color_matrix_ref"]="unknown bt709 bt2020nc ictcp"
  ["--color_matrix_dist"]="unknown bt709 bt2020nc ictcp"
  ["--rgb_matrix"]="bt601 bt709 bt2020ncl"
  ["--rgb_range"]="limited full"
  ["--rgb_transfer"]="bt709 srgb pq hlg"
  ["--rgb_out_range"]="limited full"
  ["--backend"]="auto cpu cuda sycl hip metal"
  ["--aom_ctc"]="v1.0 v2.0 v3.0 v4.0 v5.0 v6.0 v7.0"
  ["--nflx_ctc"]="v1.0"
  ["--tiny-device"]="auto cpu cuda openvino openvino-npu openvino-cpu openvino-gpu coreml coreml-ane coreml-gpu coreml-cpu rocm"
  ["--tiny_device"]="auto cpu cuda openvino openvino-npu openvino-cpu openvino-gpu coreml coreml-ane coreml-gpu coreml-cpu rocm"
  ["--dnn-ep"]="auto cpu cuda openvino openvino-npu openvino-cpu openvino-gpu coreml coreml-ane coreml-gpu coreml-cpu rocm"
  ["--dnn_ep"]="auto cpu cuda openvino openvino-npu openvino-cpu openvino-gpu coreml coreml-ane coreml-gpu coreml-cpu rocm"
